// Optical flow's shader blob accessor (ADR 0091), in place of the SDK's
// sdk/src/backends/shared/blob_accessors/ffx_opticalflow_shaderblobs.cpp, which includes
// headers generated by the SDK's shader compiler: the reflection and the permutation table
// in permutations_opticalflow.inc, the SPIR-V from Rust (src/blobs.rs), both from
// examples/ffx_shaders.rs.

#include "ffx_engine.h"

#include <FidelityFX/host/ffx_util.h>
#include "ffx_opticalflow_shaderblobs.h"
#include "opticalflow/ffx_opticalflow_private.h"

#include <cstring>

namespace {

#include "permutations_opticalflow.inc"

}  // namespace

FfxErrorCode opticalflowGetPermutationBlobByIndex(FfxOpticalflowPass passId, uint32_t permutationOptions, FfxShaderBlob* outBlob)
{
    // The generator's shaders follow `FfxOpticalflowPass`. The SDK's accessor never loads a
    // 16-bit variant.
    if (uint32_t(passId) >= uint32_t(FFX_OPTICALFLOW_PASS_COUNT))
    {
        std::memset(outBlob, 0, sizeof(FfxShaderBlob));
        return FFX_ERROR_INVALID_ARGUMENT;
    }
    // HDR input is the only option bit that maps to a define (the bits below it select the
    // SDK's wave64 and 16-bit tables).
    const uint32_t options = permutationOptions & OPTICALFLOW_HDR_COLOR_INPUT;
    return engineFfxBlob(ENGINE_FFX_OPTICAL_FLOW, g_permutations, sizeof(g_permutations) / sizeof(g_permutations[0]),
                         g_reflection, MODULE_COUNT, uint32_t(passId), 0, options, outBlob);
}

FfxErrorCode opticalflowIsWave64(uint32_t permutationOptions, bool& isWave64)
{
    // The same module either way on Vulkan: the backend requests the subgroup size.
    isWave64 = FFX_CONTAINS_FLAG(permutationOptions, OPTICALFLOW_SHADER_PERMUTATION_FORCE_WAVE64);
    return FFX_OK;
}
